elseif($view==='actions'){ $actions=smart_action_queue();?><div class="pagehead"><div><span class="eyebrow">SMART FOLLOW-UP ENGINE</span><h1>What needs attention now.</h1><p class="muted">Prioritized actions based on quote behavior, lead inactivity and order exceptions.</p></div></div><div class="smart-actions"><?php foreach($actions as $x):?><a class="card smart-action <?=e($x['priority'])?>" href="<?=e(url($x['url']))?>"><span class="pill"><?=e(strtoupper($x['priority'].' · '.$x['type']))?></span><h2><?=e($x['title'])?></h2><p><?=e($x['reason'])?></p><b>Open →</b></a><?php endforeach;if(!$actions):?><article class="card"><h2>Nothing urgent.</h2><p class="muted">The engine found no overdue sales actions.</p></article><?php endif;?></div><?php }
elseif($view==='performance'){ $perf=salesperson_performance();?><div class="pagehead"><div><span class="eyebrow">SALESPERSON PERFORMANCE</span><h1>Coach from the numbers.</h1><p class="muted">Activations, conversion, commission and response speed by salesperson.</p></div></div><div class="performance-grid"><?php foreach($perf as $i=>$x):?><article class="card performance-card"><span class="rank">#<?=$i+1?></span><h2><?=e($x['sales_agent'])?></h2><div><b><?=$x['activations']?><small>Activations</small></b><b><?=$x['conversion']?>%<small>Conversion</small></b><b>$<?=number_format((float)$x['commission'],0)?><small>Commission</small></b><b><?=number_format((float)$x['avg_response_minutes'],0)?>m<small>Avg response</small></b></div></article><?php endforeach;?></div><?php }
elseif($view==='bundlerules'){ $providers=rows("SELECT * FROM providers WHERE status='active' ORDER BY name");$rules=rows("SELECT br.*,p.name provider FROM bundle_rules br LEFT JOIN providers p ON p.id=br.provider_id ORDER BY br.active DESC,br.id DESC");?>
