class="secondary"><?=$r['active']?'Disable':'Enable'?></button></form></article><?php endforeach;?></div><?php }
elseif($view==='orders'){ $q=trim($_GET['q']??'');$os=rows("SELECT o.*,u.name customer,p.name provider FROM orders o JOIN users u ON u.id=o.user_id JOIN providers p ON p.id=o.provider_id WHERE (?='' OR o.public_id LIKE ? OR u.name LIKE ? OR o.provider_reference LIKE ?) ORDER BY o.id DESC LIMIT 100",[$q,'%'.$q.'%','%'.$q.'%','%'.$q.'%']);?><div class="pagehead"><div><span class="eyebrow">FULFILMENT</span><h1>Orders</h1></div><form method="get" class="searchbar order-search"><input type="hidden" name="page" value="admin"><input type="hidden" name="view" value="orders"><input name="q" value="<?=e($q)?>" placeholder="Order, customer or provider ref"><button>Search</button></form></div><div class="grid order-admin-grid"><?php foreach($os as $o):?><article class="card"><div class="row between"><span class="pill <?=e(sla_state($o))?>"><?=e($o['public_id'])?></span><span class="status-chip <?=e($o['commission_status'])?>">COMMISSION <?=e(strtoupper($o['commission_status']))?></span></div><h3><?=e($o['customer'])?> · <?=e($o['provider'])?></h3><p><?=e(ucwords(str_replace('_',' ',$o['status'])))?><?php if(!$o['first_contact_at']&&$o['status']==='submitted'):?> · <strong><?=sla_minutes($o)?> min SLA</strong><?php endif;?></p><form method="post"><input type="hidden" name="_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?=$o['id']?>"><div class="formgrid"><label>Status<select name="status"><?php foreach(['submitted','reviewing','need_information','ready_to_process','submitted_to_provider','appointment_confirmed','activated','completed','cancelled','rejected'] as $st):?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></label><label>Lost reason<select name="lost_reason"><option value="">—</option><?php foreach(lost_reasons() as $r):?><option <?=$o['lost_reason']===$r?'selected':''?>><?=e($r)?></option><?php endforeach;?></select></label><label>Provider reference<input name="provider_reference" value="<?=e($o['provider_reference']??'')?>"></label><label>Appointment<input type="datetime-local" name="appointment_at" value="<?=e($o['appointment_at']??'')?>"></label><label>Salesperson<input name="sales_agent" value="<?=e($o['sales_agent']??'')?>"></label><label>Commission amount<input type="number" min="0" step="0.01" name="commission_amount" value="<?=e((string)($o['commission_amount']??0))?>"></label><label>Commission status<select name="commission_status"><?php foreach(['pending','approved','paid','void'] as $cs):?><option value="<?=$cs?>" <?=$o['commission_status']===$cs?'selected':''?>><?=e(ucfirst($cs))?></option><?php endforeach;?></select></label></div><button>Update order</button></form><details><summary>Internal note / customer update</summary><form method="post"><input type="hidden" name="_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="communication"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="user_id" value="<?=$o['user_id']?>"><label>Type<select name="visibility"><option value="internal">Internal note</option><option value="customer">Customer update</option></select></label><input type="hidden" name="kind" value="note"><label>Subject<input name="subject"></label><label>Message<textarea name="message" required></textarea></label><button>Save update</button></form></details></article><?php endforeach;if(!$os):?><article class="card empty-state"><h3>No orders found</h3><p class="muted">Try another order ID, customer name or provider reference.</p></article><?php endif;?></div><?php }
